func parseRequest(payload []byte) (cmd string, args []string, err error) {
	trimmed := bytes.TrimSpace(payload)
	...
	fields := bytes.Fields(trimmed)
	...
	cmdField := fields[0]

	switch {
	case equalFoldASCII(cmdField, "GET"):
		if len(fields) != 2 && len(fields) != 3 {
			return "", nil, fmt.Errorf("GET expects key [request-id]: %w", errMalformed)
		}
		cmd = "GET"
	case equalFoldASCII(cmdField, "SCAN"):
		if len(fields) != 3 && len(fields) != 4 {
			return "", nil, fmt.Errorf("SCAN expects start_key limit [request-id]: %w", errMalformed)
		}
		cmd = "SCAN"
	default:
		return "", nil, errUnknownCommand
	}
	...
}

func equalFoldASCII(b []byte, s string) bool {
	if len(b) != len(s) {
		return false
	}
	for i := 0; i < len(b); i++ {
		cb := b[i]
		cs := s[i]
		if 'A' <= cs && cs <= 'Z' {
			cs += 'a' - 'A'
		}
		if 'A' <= cb && cb <= 'Z' {
			cb += 'a' - 'A'
		}
		if cb != cs {
			return false
		}
	}
	return true
}

func (s *Server) handleRequest(idx int, payload []byte) []byte {
	cmd, args, err := parseRequest(payload)
	if err != nil {
		return []byte(fmt.Sprintf("ERR %v", err))
	}

	...
	switch cmd {
	case "GET":
		...
	case "SCAN":
		...
	default:
		return []byte("ERR unknown command")
	}
}

func appendKey(buf []byte, prefix string, keyIdx int) []byte {
	buf = append(buf, prefix...)
	if keyIdx < 100000000 {
		start := len(buf)
		buf = append(buf, '0', '0', '0', '0', '0', '0', '0', '0')
		for i := 7; i >= 0; i-- {
			buf[start+i] = byte('0' + keyIdx%10)
			keyIdx /= 10
		}
		return buf
	}
	return strconv.AppendInt(buf, int64(keyIdx), 10)
}

func (s *Server) openWorker(idx int) (*net.UDPConn, int, error) {
	attachPolicy := s.policy != nil && s.policy.program != nil && idx == 0
	var attachErr error

	lc := net.ListenConfig{Control: func(network, address string, c syscall.RawConn) error {
		return c.Control(func(fd uintptr) {
			if err := unix.SetsockoptInt(int(fd), unix.SOL_SOCKET, unix.SO_REUSEADDR, 1); err != nil && attachErr == nil {
				attachErr = fmt.Errorf("SO_REUSEADDR: %w", err)
				return
			}
			if err := unix.SetsockoptInt(int(fd), unix.SOL_SOCKET, unix.SO_REUSEPORT, 1); err != nil && attachErr == nil {
				attachErr = fmt.Errorf("SO_REUSEPORT: %w", err)
				return
			}
			if attachPolicy && attachErr == nil {
				if err := s.policy.attach(int(fd)); err != nil {
					attachErr = err
				}
			}
		})
	}}

	pc, err := lc.ListenPacket(context.Background(), "udp", s.cfg.ListenAddr)
	if err != nil {
		return nil, -1, err
	}
	if attachErr != nil {
		pc.Close()
		return nil, -1, attachErr
	}

	udpConn := pc.(*net.UDPConn)
	var fd int
	raw, err := udpConn.SyscallConn()
	if err != nil {
		udpConn.Close()
		return nil, -1, err
	}
	if err := raw.Control(func(value uintptr) {
		fd = int(value)
	}); err != nil {
		udpConn.Close()
		return nil, -1, err
	}

	return udpConn, fd, nil
}

func (s *Server) spawnWorker(ctx context.Context, idx int, conn *net.UDPConn) {
	s.wg.Add(1)
	go func() {
		defer s.wg.Done()
		buf := make([]byte, 16*1024)

		for {
			n, addr, err := conn.ReadFromUDP(buf)
			if err != nil {
				select {
				case <-ctx.Done():
					return
				default:
				}
				if errors.Is(err, net.ErrClosed) {
					return
				}
				s.logger.Printf("worker=%d read error: %v", idx, err)
				continue
			}

			response := s.handleRequest(idx, buf[:n])
			if response == nil {
				continue
			}

			if _, err := conn.WriteToUDP(response, addr); err != nil {
				if errors.Is(err, net.ErrClosed) {
					return
				}
				s.logger.Printf("worker=%d write error: %v", idx, err)
			}
		}
	}()
}

